# Root-only observer. It schedules one explicit pinned task, retains worker handle while alive,
# then emits bounded kernel/.NET/receipt/scheduler joins. It never touches desktop CAS or stops processes.
[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$PlanPath,
  [Parameter(Mandatory)][string]$OutputPath,
  [ValidateRange(60,1100)][int]$DeadlineSeconds=1100
)
$ErrorActionPreference='Stop'
function Read-BoundedJson([string]$Path,[int64]$Limit=2097152){$item=Get-Item -LiteralPath $Path -Force -ErrorAction Stop;if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0 -or $item.Length -gt $Limit){throw "bounded observer input rejected: $Path"};return [IO.File]::ReadAllText($item.FullName)|ConvertFrom-Json}
function Require([bool]$Condition,[string]$Message){if(-not $Condition){throw $Message}}
function Source([object]$Plan,[string]$Name){$item=$Plan.sources.PSObject.Properties[$Name];if($null -eq $item){throw "plan source missing: $Name"};Require ([string]$item.Value.path -and [string]$item.Value.sha256 -match '^[0-9a-fA-F]{64}$') "plan source pin invalid: $Name";return $item.Value}
function Hash-Matches([string]$Path,[string]$Expected){$item=Get-Item -LiteralPath $Path -Force -ErrorAction Stop;if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0){return $false};return (Get-FileHash -LiteralPath $item.FullName -Algorithm SHA256).Hash.ToLowerInvariant() -ceq $Expected.ToLowerInvariant()}
function Write-AtomicFresh([string]$Path,[object]$Value){if(Test-Path -LiteralPath $Path){throw "observer output must be fresh: $Path"};$parent=Split-Path -Parent ([IO.Path]::GetFullPath($Path));if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$Path.$PID.$([guid]::NewGuid().ToString('N')).tmp";$stream=[IO.File]::Open($tmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$bytes=[Text.Encoding]::UTF8.GetBytes(($Value|ConvertTo-Json -Depth 18)+"`r`n");$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Move($tmp,$Path)}
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class Sr0FreshObserverKernelV4 {
  [DllImport("kernel32.dll",EntryPoint="WaitForSingleObject",SetLastError=true)] static extern uint WaitForSingleObject(IntPtr handle,uint milliseconds);
  [DllImport("kernel32.dll",EntryPoint="GetExitCodeProcess",SetLastError=true)] static extern bool GetExitCodeProcess(IntPtr handle,out uint code);
  public static bool Terminal(IntPtr handle,out uint code){code=259;if(handle==IntPtr.Zero)return false;if(WaitForSingleObject(handle,0)!=0)return false;if(!GetExitCodeProcess(handle,out code))return false;return code!=259;}
  [DllImport("kernel32.dll",EntryPoint="WTSGetActiveConsoleSessionId")] static extern uint WTSGetActiveConsoleSessionId();
  public static long SignedDword(uint code){return unchecked((int)code);}
  public static uint ActiveConsoleSession(){return WTSGetActiveConsoleSessionId();}
}
'@
$plan=Read-BoundedJson $PlanPath;Require ([string]$plan.schema -eq 'sr0-display-selfjob-v4-fresh-one-run') 'fresh plan schema mismatch';$factoryRoot=[IO.Path]::GetFullPath([string]$plan.factoryRoot);$factoryPrefix=$factoryRoot.TrimEnd('\')+'\';Require ([IO.Path]::GetFullPath($OutputPath).StartsWith($factoryPrefix,[StringComparison]::OrdinalIgnoreCase)) 'observer output must remain in factory namespace';$manifest=[IO.Path]::GetFullPath([string]$plan.manifestPath);$launcherReceipt=[IO.Path]::GetFullPath((Join-Path ([string]$plan.runRoot) 'launcher-receipt.json'));Require (-not(Test-Path -LiteralPath $launcherReceipt)) 'launcher receipt must be fresh before schedule';Require (Test-Path -LiteralPath ([string]$plan.lockPath) -PathType Leaf) 'desktop CAS lock missing'
$names=@('frozenTask','helper','parser','worker','launcherHelper','collector','coordinator','wrapper','workloadExe','rendererDll','presentMonExe');$pinned=@{};foreach($name in $names){$s=Source $plan $name;Require (Test-Path -LiteralPath ([string]$s.path) -PathType Leaf) "pinned source missing: $name";Require (Hash-Matches ([string]$s.path) ([string]$s.sha256)) "pinned source hash mismatch: $name";$pinned[$name]=$s}
$schedule=[string]$plan.schedulePath;Require (Test-Path -LiteralPath $schedule -PathType Leaf) 'schedule source missing';$scheduleSha=(Get-FileHash -LiteralPath $schedule -Algorithm SHA256).Hash.ToLowerInvariant();$worker=[string]$pinned.worker.path;$manifestDir=Split-Path -Parent $manifest;if(-not(Test-Path -LiteralPath $manifestDir)){[IO.Directory]::CreateDirectory($manifestDir)|Out-Null};$taskName=[string]$plan.taskName
$workerPid=$null;$workerProcess=$null;$workerHandle=[IntPtr]::Zero;$workerHandleAcquired=$false;$workerCommandLine=$null;$workerPath=$null;$workerStartUtc=$null;$workerSession=$null;$workerSessionMatch=$false;$kernelTerminal=$false;[uint32]$kernelRaw=259;$kernelSigned=$null;$dotnetExit=$null;$schedulerState=$null;$schedulerRunning=$null;$launcher=$null;$errors=New-Object 'System.Collections.Generic.List[string]';$scheduleInvoked=$false;$scheduleInvokedAt=$null;$deadline=[DateTime]::UtcNow.AddSeconds($DeadlineSeconds)
try {
  $scheduleParams=@{WorkerPath=[string]$pinned.worker.path;LauncherHelperPath=[string]$pinned.launcherHelper.path;CollectorPath=[string]$pinned.collector.path;CoordinatorPath=[string]$pinned.coordinator.path;WrapperPath=[string]$pinned.wrapper.path;ManifestPath=$manifest;Base=[string]$plan.base;ControlRoot=[string]$plan.controlRoot;FrozenTaskPath=[string]$pinned.frozenTask.path;HelperPath=[string]$pinned.helper.path;ParserPath=[string]$pinned.parser.path;WorkloadExe=[string]$pinned.workloadExe.path;RendererDll=[string]$pinned.rendererDll.path;PresentMonExe=[string]$pinned.presentMonExe.path;FrozenTaskSha256=[string]$pinned.frozenTask.sha256;HelperSha256=[string]$pinned.helper.sha256;ParserSha256=[string]$pinned.parser.sha256;WorkerSha256=[string]$pinned.worker.sha256;LauncherHelperSha256=[string]$pinned.launcherHelper.sha256;CollectorSha256=[string]$pinned.collector.sha256;CoordinatorSha256=[string]$pinned.coordinator.sha256;WrapperSha256=[string]$pinned.wrapper.sha256;WorkloadExeSha256=[string]$pinned.workloadExe.sha256;RendererDllSha256=[string]$pinned.rendererDll.sha256;PresentMonSha256=[string]$pinned.presentMonExe.sha256;TaskName=$taskName;RunRoot=[string]$plan.runRoot;LockPath=[string]$plan.lockPath;Tag=$taskName;Warmup=[int]$plan.warmup;Measure=[int]$plan.measure;Rows=[int]$plan.rows;KeyRate=[double]$plan.keyRate}
  $scheduleInvokedAt=[DateTimeOffset]::UtcNow;& $schedule @scheduleParams | Out-Null;$scheduleInvoked=$true
  $workerArgPattern='(?i)(?:^|\s)-File\s+"?'+[regex]::Escape([string]$pinned.worker.path)+'"?(?:\s|$)';$manifestArgPattern='(?i)(?:^|\s)-ManifestPath\s+"?'+[regex]::Escape($manifest)+'"?(?:\s|$)';$expectedWorkerExe=[IO.Path]::GetFullPath((Join-Path $PSHOME 'powershell.exe'));$activeConsole=[Sr0FreshObserverKernelV4]::ActiveConsoleSession()
  while($null -eq $workerProcess -and [DateTime]::UtcNow -lt $deadline){$items=@(Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction Stop);foreach($item in $items){$cmd=[string]$item.CommandLine;if($cmd.Length -gt 65536 -or $cmd -notmatch $workerArgPattern -or $cmd -notmatch $manifestArgPattern){continue};$candidate=$null;try{$candidate=Get-Process -Id ([int]$item.ProcessId) -ErrorAction Stop;if($candidate.HasExited){$candidate.Dispose();continue};$candidateHandle=$candidate.Handle;if($candidateHandle -eq [IntPtr]::Zero){$candidate.Dispose();continue};$candidatePath=[IO.Path]::GetFullPath($candidate.MainModule.FileName);$candidateStart=$candidate.StartTime.ToUniversalTime();$candidateSession=$candidate.SessionId;if(-not $candidatePath.Equals($expectedWorkerExe,[StringComparison]::OrdinalIgnoreCase) -or $candidateStart -lt $scheduleInvokedAt.UtcDateTime -or ($activeConsole -ne [uint32]::MaxValue -and $activeConsole -ne 0 -and $candidateSession -ne [int]$activeConsole)){[void]$candidate.Dispose();continue};$workerProcess=$candidate;$workerPid=$candidate.Id;$workerHandle=$candidateHandle;$workerHandleAcquired=$true;$workerCommandLine=$cmd;$workerPath=$candidatePath;$workerStartUtc=$candidateStart.ToString('o');$workerSession=$candidateSession;$workerSessionMatch=($activeConsole -eq [uint32]::MaxValue -or $activeConsole -eq 0 -or $candidateSession -eq [int]$activeConsole);break}catch{if($candidate){try{$candidate.Dispose()}catch{}}}};if($null -eq $workerProcess){Start-Sleep -Seconds 1}}
  if($null -eq $workerProcess){throw 'run-once worker not found before bounded deadline'}
  while(-not $workerProcess.HasExited -and [DateTime]::UtcNow -lt $deadline){Start-Sleep -Seconds 1}
  if(-not $workerProcess.HasExited){throw 'run-once worker did not exit before bounded deadline'}
  $kernelTerminal=[Sr0FreshObserverKernelV4]::Terminal($workerHandle,[ref]$kernelRaw);$workerProcess.Refresh();$dotnetExit=[int64]$workerProcess.ExitCode;$kernelSigned=[Sr0FreshObserverKernelV4]::SignedDword($kernelRaw);if(-not $kernelTerminal){throw 'worker original handle is not terminal'};if($kernelSigned -ne $dotnetExit){throw 'worker kernel/.NET exit identity mismatch'};if($dotnetExit -ne 0){throw "run-once worker exit was nonzero: $dotnetExit"}
  $launcher=Read-BoundedJson $launcherReceipt;Require ([string]$launcher.kind -eq 'sr0-display-launcher-v4') 'launcher receipt kind mismatch';Require ([string]$launcher.status -eq 'passed') 'launcher receipt is not passed';Require ([string]$launcher.taskName -ceq $taskName) 'launcher receipt task mismatch';Require ([bool]$launcher.aggregateDescendantsQuiesced -and [int64]$launcher.aggregateActiveAfter -eq 1) 'launcher aggregate self-only proof missing';if([bool]$launcher.aggregateCleanupAttempted){Require ([bool]$launcher.aggregateCleanupSelfOnly) 'launcher cleanup self-only proof missing'}
  $schedulerDeadline=[DateTime]::UtcNow.AddSeconds(15);do{$task=Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue;if($null -eq $task){$schedulerState='absent';$schedulerRunning=$false;break};$schedulerState=[string]$task.State;$schedulerRunning=($schedulerState -eq 'Running' -or $schedulerState -eq 'Queued');if($schedulerRunning){Start-Sleep -Seconds 1}}while($schedulerRunning -and [DateTime]::UtcNow -lt $schedulerDeadline);if($schedulerRunning){throw "scheduled task remains active: $schedulerState"}
}catch{[void]$errors.Add($_.Exception.Message)}
finally{$out=[ordered]@{kind='sr0-display-selfjob-v4-fresh-observer';status=if($errors.Count -eq 0){'passed'}else{'held'};planPath=[IO.Path]::GetFullPath($PlanPath);schedulePath=[IO.Path]::GetFullPath($schedule);scheduleSha256=$scheduleSha;scheduleInvoked=$scheduleInvoked;scheduleInvokedAt=if($scheduleInvokedAt){$scheduleInvokedAt.ToString('o')}else{$null};taskName=$taskName;manifestPath=$manifest;launcherReceiptPath=$launcherReceipt;workerPid=$workerPid;workerCommandLine=$workerCommandLine;workerPath=$workerPath;workerStartTimeUtc=$workerStartUtc;workerSession=$workerSession;workerSessionMatch=$workerSessionMatch;workerOriginalHandleAcquired=$workerHandleAcquired;workerKernelTerminal=$kernelTerminal;workerExitRaw=$kernelRaw;workerExitSigned=$kernelSigned;workerExitDotnet=$dotnetExit;launcherStatus=if($launcher){$launcher.status}else{$null};aggregateActiveAfter=if($launcher){$launcher.aggregateActiveAfter}else{$null};aggregateDescendantsQuiesced=if($launcher){$launcher.aggregateDescendantsQuiesced}else{$null};schedulerState=$schedulerState;schedulerRunning=$schedulerRunning;errors=@($errors);checkedAt=[DateTimeOffset]::UtcNow.ToString('o')};Write-AtomicFresh $OutputPath $out;if($workerProcess){try{$workerProcess.Dispose()}catch{}}}
if($errors.Count -ne 0){exit 1}else{exit 0}
